window.__finlexDocLoaded(10199,{"id":10199,"articles":[{"id":1000827,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes the three-category classification model for debt securities — Held-to-Maturity (HTM), Trading, and Available-for-Sale (AFS) — and their balance sheet/OCI accounting.","seq":0},{"id":1000828,"no":"ASC 320-10","heading":"HTM, Trading & Available-for-Sale (AFS) Debt Classification","text":"• Held-to-Maturity — HTM (ASC 320-10-25-1): Amortized cost; requires positive intent and ability to hold to maturity (selling HTM triggers strict 'tainting' rules).\n• Trading: Measured at fair value through net income (FVTPL).\n• Available-for-Sale — AFS: Measured at fair value with unrealized gains/losses in OCI (recycled to net income upon sale); credit losses recorded via allowance under ASC 326-30 (capped at fair value floor).","seq":1},{"id":1000829,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Classification Driver: US GAAP classifies debt securities by management intent (HTM/Trading/AFS) without an SPPI cash-flow test; IFRS 9 classifies financial assets by BOTH Business Model AND SPPI contractual cash flow characteristics.","seq":2},{"id":1000830,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
